@media (prefers-reduced-motion: reduce){
  *,
  *::before,
  *::after {
    animation-duration:var(--motion-instant) !important;
    animation-iteration-count:1 !important;
    scroll-behavior:auto !important;
    transition-duration:var(--motion-instant) !important;
  }
}

