  font-size:var(--font-size-28);
  font-weight:var(--font-weight-950);
  line-height:var(--line-height-1-12);
  font-variant-numeric:tabular-nums;
  overflow-wrap:anywhere;
}

.premium-kpi-description,
.metric-card small,
.dashboard-kpi-card small,
.report-kpi-card p,
.kpi-card small,
.executive-kpi-card small {
  display:block;
  margin-top:auto;
  color:var(--text-soft);
  font-size:var(--font-size-12);
  font-weight:var(--font-weight-800);
  line-height:var(--line-height-1-35);
  overflow-wrap:anywhere;
}

.premium-stat-card {
  grid-template-columns:minmax(0, 1fr);
  align-content:space-between;
}

.premium-stat-card-metric {
  display:grid;
  gap:var(--space-8);
  min-width:0;
}

.premium-stat-chart {
  min-height:96px;
  border:1px dashed var(--line);
  border-radius:var(--radius-card);
  padding:var(--space-12);
  background:var(--surface-muted);
}

.premium-widget,
.dashboard-experience-widget,
.dashboard-widget-card,
.dashboard-widget-catalog-card,
.procurement-analytics-widget {
  min-height:100%;
}

.dashboard-widget-card,
.dashboard-widget-catalog-card {
  padding:var(--space-16);
  background:linear-gradient(145deg, var(--surface-raised), var(--surface));
}

.dashboard-widget-card-meta span,
.dashboard-widget-catalog-meta span,
.premium-action-label {
  display:inline-flex;
  align-items:center;
  min-height:26px;
  border:1px solid var(--line);
  border-radius:var(--radius-full);
  padding:var(--space-2) var(--space-8);
  background:var(--surface-muted);
  color:var(--muted-strong);
  font-size:var(--font-size-11);
  font-weight:var(--font-weight-950);
  line-height:var(--line-height-1-2);
}

.premium-action-card {
  width:100%;
  min-height:156px;
  grid-template-columns:var(--icon-frame-xl) minmax(0, 1fr) auto;
  align-items:center;
  gap:var(--space-16);
  border:1px solid var(--line-soft);
  color:var(--text);
  text-align:left;
  cursor:pointer;
}

.premium-action-card:disabled {
  cursor:not-allowed;
  opacity:.68;
}

.premium-action-copy {
  display:grid;
  gap:var(--space-4);
  min-width:0;
}

.premium-action-copy strong {
  color:var(--text);
  font-size:var(--font-size-18);
  font-weight:var(--font-weight-950);
  line-height:var(--line-height-1-2);
}

.premium-action-copy small {
  color:var(--text-soft);
  font-size:var(--font-size-13);
  font-weight:var(--font-weight-780);
  line-height:var(--line-height-1-45);
}

.premium-info-card {
  min-height:132px;
}

.premium-empty-card,
.dashboard-widget-empty,
.dashboard-widget-placeholder {
  display:grid;
  grid-template-columns:var(--icon-frame-xl) minmax(0, 1fr);
  gap:var(--space-16);
  align-items:center;
  min-height:156px;
  border-style:dashed;
  background:linear-gradient(135deg, var(--surface), var(--surface-muted));
}

.premium-empty-card.compact {
  grid-template-columns:var(--icon-frame-lg) minmax(0, 1fr);
  min-height:112px;
  padding:var(--space-12);
}

.premium-empty-actions {
  display:flex;
  flex-wrap:wrap;
  gap:var(--space-8);
  margin-top:var(--space-12);
}

.premium-card-loading {
  display:grid;
  gap:var(--space-8);
  min-height:112px;
  align-content:center;
}

.premium-card-loading span {
  display:block;
  height:12px;
  border-radius:var(--radius-full);
  background:linear-gradient(90deg, var(--surface-muted), var(--surface-subtle), var(--surface-muted));
  background-size:220% 100%;
  animation:premiumCardLoading var(--motion-loading) var(--motion-ease-standard) infinite;
}

.premium-card-loading span:first-child {
  width:46%;
  height:18px;
}

.premium-card-loading span:nth-child(2) {
  width:82%;
}

.premium-card-loading span:nth-child(3) {
  width:64%;
}

@keyframes premiumCardLoading {
  0% { background-position:120% 0 }
  100% { background-position:-120% 0 }
}

@media (hover: hover) and (pointer: fine){
  .premium-card.interactive:hover,
  .premium-action-card:hover:not(:disabled),
  .card:hover,
  .dashboard-panel:hover,
  .metric-card:hover,
  .dashboard-kpi-card:hover,
  .dashboard-widget-card:hover,
  .dashboard-widget-catalog-card:hover,
  .workspace-welcome-panel.action-card:hover,
  .report-center-card:hover {
    border-color:var(--accent-line);
    box-shadow:var(--shadow-button-hover);
    transform:translateY(calc(var(--space-2) * -1));
  }
}

.premium-action-card:focus-visible,
.premium-card.interactive:focus-visible,
.workspace-welcome-panel.action-card:focus-visible {
  outline:2px solid var(--accent);
  outline-offset:2px;
}

@media (max-width: 980px){
  .premium-card-header,
  .card > :where(.section-header, .dashboard-panel-header):first-child,
  .dashboard-experience-widget-header {
    align-items:flex-start;
    flex-direction:column;
  }

  .premium-card-actions,
  .premium-card-actions .btn,
  .premium-card-footer,
  .dashboard-widget-card-actions,
  .dashboard-widget-card-actions .btn {
    width:100%;
    justify-content:flex-start;
  }

  .premium-action-card {
    grid-template-columns:var(--icon-frame-xl) minmax(0, 1fr);
  }

  .premium-action-label {
    grid-column:1 / -1;
    justify-self:start;
  }
}

@media (max-width: 640px){
  .premium-card,
  .card,
  .dashboard-panel,
  .metric-card,
  .dashboard-kpi-card,
  .dashboard-widget-card,
  .dashboard-widget-catalog-card {
    padding:var(--space-12);
  }

  .premium-card-heading,
  .premium-action-card,
  .premium-empty-card,
  .dashboard-widget-empty,
  .dashboard-widget-placeholder,
  .premium-empty-card.compact {
    grid-template-columns:1fr;
  }

  .premium-card-icon,
  .dashboard-widget-card-icon,
  .dashboard-widget-empty-icon {
    width:var(--icon-frame-lg);
    height:var(--icon-frame-lg);
  }

  .premium-kpi-value,
  .metric-card strong,
  .dashboard-kpi-card strong,
  .report-kpi-card strong,
  .kpi-card strong,
  .executive-kpi-card strong {
    font-size:var(--font-size-24);
  }
}

/* Faz 35.8 Loading, Skeleton & Progress */
.premium-skeleton,
.premium-skeleton-stack,
.premium-skeleton-block {
  min-width:0;
}

.premium-skeleton {
  display:block;
  width:var(--premium-skeleton-width, 100%);
  height:var(--premium-skeleton-height, 12px);
  border-radius:var(--radius-full);
  background:linear-gradient(90deg, var(--surface-muted), var(--surface-subtle), var(--surface-muted));
  background-size:220% 100%;
  animation:premiumSkeletonShimmer var(--motion-loading) var(--motion-ease-standard) infinite;
}

.premium-skeleton.no-animation,
.premium-skeleton-stack.no-animation .premium-skeleton,
.premium-skeleton-block.no-animation .premium-skeleton {
  animation:none;
}

.premium-skeleton-stack {
  display:grid;
  gap:var(--space-8);
}

.premium-skeleton-stack .premium-skeleton:nth-child(2n) { width:min(var(--premium-skeleton-width, 100%), 86%) }
.premium-skeleton-stack .premium-skeleton:nth-child(3n) { width:min(var(--premium-skeleton-width, 100%), 72%) }

.premium-skeleton-title {
  height:var(--premium-skeleton-height, 24px);
  border-radius:var(--radius-lg);
}

.premium-skeleton-avatar {
  width:var(--premium-skeleton-width, var(--icon-frame-xl));
  height:var(--premium-skeleton-height, var(--icon-frame-xl));
  border-radius:var(--radius-card);
}

.premium-skeleton-button {
  height:var(--premium-skeleton-height, var(--touch-target));
  border-radius:var(--radius-button);
}

.premium-table-skeleton-line.premium-skeleton {
  width:min(100%, 180px);
  height:12px;
}

.premium-skeleton-block {
  display:grid;
  gap:var(--space-12);
  border:1px solid var(--line-soft);
  border-radius:var(--radius-card);
  padding:var(--space-16);
  background:linear-gradient(180deg, var(--surface-raised), var(--surface));
  box-shadow:var(--shadow-card);
}

.premium-skeleton-card,
.premium-skeleton-widget {
  min-height:132px;
}

.premium-skeleton-form {
  grid-template-columns:repeat(2, minmax(0, 1fr));
}

.premium-skeleton-form-field {
  display:grid;
  gap:var(--space-8);
  min-width:0;
}

.premium-skeleton-table {
  gap:var(--space-8);
  overflow:hidden;
}

.premium-skeleton-table-row {
  display:grid;
  grid-template-columns:repeat(var(--premium-skeleton-columns, 4), minmax(0, 1fr));
  gap:var(--space-12);
  align-items:center;
  min-height:44px;
  border-bottom:1px solid var(--line-soft);
}

.premium-skeleton-table-row:last-child {
  border-bottom:0;
}

.premium-skeleton-dashboard {
  width:100%;
  gap:var(--space-16);
  border:0;
  padding:0;
  background:transparent;
  box-shadow:var(--shadow-none);
}

.premium-skeleton-hero {
  display:grid;
  gap:var(--space-12);
  min-height:128px;
  border:1px solid var(--line-soft);
  border-radius:var(--radius-card);
  padding:var(--space-20);
  background:linear-gradient(180deg, var(--surface-raised), var(--surface));
  box-shadow:var(--shadow-card);
}

.premium-skeleton-kpi-grid {
  display:grid;
  grid-template-columns:repeat(4, minmax(0, 1fr));
  gap:var(--space-12);
}

.premium-skeleton-kpi {
  min-height:124px;
}

.premium-spinner {
  display:inline-flex;
  align-items:center;
  justify-content:center;
  gap:var(--space-8);
  min-width:0;
  color:var(--accent);
  vertical-align:middle;
}

.premium-spinner.tone-neutral { color:var(--muted-strong) }
.premium-spinner.tone-info { color:var(--accent) }
.premium-spinner.tone-success { color:var(--success) }
.premium-spinner.tone-warning { color:var(--warning) }
.premium-spinner.tone-danger { color:var(--danger) }

.premium-spinner-ring {
  display:block;
  width:24px;
  height:24px;
  border:3px solid color-mix(in srgb, currentColor 18%, transparent);
  border-top-color:currentColor;
  border-radius:var(--radius-circle);
  animation:premiumLoadingSpin var(--motion-spinner) var(--motion-ease-linear) infinite;
}

.premium-spinner.size-small .premium-spinner-ring {
  width:18px;
  height:18px;
  border-width:2px;
}

.premium-spinner.size-large .premium-spinner-ring {
  width:38px;
  height:38px;
  border-width:4px;
}

.premium-spinner-label {
  min-width:0;
  color:var(--text-soft);
  font-size:var(--font-size-13);
  font-weight:var(--font-weight-850);
  line-height:var(--line-height-1-35);
  overflow-wrap:anywhere;
}

.premium-linear-progress {
  display:grid;
  gap:var(--space-8);
  min-width:0;
  color:var(--accent);
  --premium-progress-color:var(--accent);
  --premium-progress-soft:var(--accent-soft);
  --premium-progress-line:var(--accent-line);
  --premium-progress-track-height:10px;
}

.premium-linear-progress.size-small { --premium-progress-track-height:6px }
.premium-linear-progress.size-large { --premium-progress-track-height:14px }

.premium-linear-progress.tone-neutral,
.premium-progress.tone-neutral,
.premium-circular-progress.tone-neutral {
  --premium-progress-color:var(--muted-strong);
  --premium-progress-soft:var(--surface-muted);
  --premium-progress-line:var(--line);
  color:var(--muted-strong);
}

.premium-linear-progress.tone-info,
.premium-progress.tone-info,
.premium-circular-progress.tone-info {
  --premium-progress-color:var(--accent);
  --premium-progress-soft:var(--accent-soft);
  --premium-progress-line:var(--accent-line);
  color:var(--accent);
}

.premium-linear-progress.tone-success,
.premium-progress.tone-success,
.premium-circular-progress.tone-success {
  --premium-progress-color:var(--success);
  --premium-progress-soft:var(--success-soft);
  --premium-progress-line:var(--success-line);
  color:var(--success);
}

.premium-linear-progress.tone-warning,
.premium-progress.tone-warning,
.premium-circular-progress.tone-warning {
  --premium-progress-color:var(--warning);
  --premium-progress-soft:var(--warning-soft);
  --premium-progress-line:var(--warning-line);
  color:var(--warning);
}

.premium-linear-progress.tone-danger,
.premium-progress.tone-danger,
.premium-circular-progress.tone-danger {
  --premium-progress-color:var(--danger);
  --premium-progress-soft:var(--danger-soft);
  --premium-progress-line:var(--danger-line);
  color:var(--danger);
}

.premium-progress-header {
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:var(--space-8);
  min-width:0;
}

.premium-progress-label,
.premium-progress-meta {
  min-width:0;
  color:var(--text-soft);
  font-size:var(--font-size-12);
  font-weight:var(--font-weight-900);
  line-height:var(--line-height-1-2);
  overflow-wrap:anywhere;
}

.premium-progress-meta {
  display:inline-flex;
  align-items:center;
  justify-content:flex-end;
  gap:var(--space-8);
  flex:0 0 auto;
  color:var(--muted-strong);
  font-variant-numeric:tabular-nums;
}

.premium-progress-meta em {
  font-style:normal;
  color:var(--premium-progress-color);
}

.premium-progress-meta strong {
  color:var(--text);
  font-weight:var(--font-weight-950);
}

.premium-progress-track {
  position:relative;
  width:100%;
  height:var(--premium-progress-track-height);
  overflow:hidden;
  border:1px solid var(--premium-progress-line);
  border-radius:var(--radius-full);
  background:var(--surface-subtle);
  box-shadow:inset 0 1px 2px var(--color-rgba-15-23-42-08);
}

.premium-progress-bar {
  display:block;
  width:var(--premium-progress-value, 0%);
  min-width:4px;
  height:100%;
  border-radius:var(--radius-full);
  background:linear-gradient(90deg, var(--premium-progress-color), color-mix(in srgb, var(--premium-progress-color) 72%, var(--surface)));
  box-shadow:0 0 0 1px color-mix(in srgb, var(--premium-progress-color) 18%, transparent), 0 8px 20px color-mix(in srgb, var(--premium-progress-color) 18%, transparent);
  transition:width var(--motion-normal) var(--motion-ease-standard), background var(--motion-fast) var(--motion-ease-standard);
}

.premium-linear-progress.indeterminate .premium-progress-bar {
  width:42%;
  min-width:42%;
  animation:premiumProgressIndeterminate var(--motion-attention) var(--motion-ease-in-out) infinite;
}

.premium-progress-description {
  color:var(--text-soft);
  font-size:var(--font-size-12);
  font-weight:var(--font-weight-780);
  line-height:var(--line-height-1-35);
  overflow-wrap:anywhere;
}

.premium-circular-progress {
  display:inline-flex;
  align-items:center;
  justify-content:center;
  --premium-progress-ring-size:72px;
  --premium-progress-ring-inset:7px;
}

.premium-circular-progress.size-small {
  --premium-progress-ring-size:48px;
  --premium-progress-ring-inset:5px;
}

.premium-circular-progress.size-large {
  --premium-progress-ring-size:108px;
  --premium-progress-ring-inset:9px;
}

.premium-circular-progress-ring {
  position:relative;
  display:grid;
  place-items:center;
  width:var(--premium-progress-ring-size);
  height:var(--premium-progress-ring-size);
  border-radius:var(--radius-circle);
  background:conic-gradient(var(--premium-progress-color) var(--premium-progress-value, 0%), var(--surface-subtle) 0);
  box-shadow:var(--shadow-xs);
}

.premium-circular-progress-ring::before {
  content:"";
  position:absolute;
  inset:var(--premium-progress-ring-inset);
  border-radius:var(--radius-circle);
  background:var(--surface);
  box-shadow:inset 0 0 0 1px var(--line-soft);
}

.premium-circular-progress.indeterminate .premium-circular-progress-ring {
  background:conic-gradient(from 20deg, transparent 0 18%, var(--premium-progress-color) 19% 44%, transparent 45% 100%);
  animation:premiumLoadingSpin var(--motion-spinner) var(--motion-ease-linear) infinite;
}

.premium-circular-progress-value {
  position:relative;
  z-index:1;
  max-width:76%;
  color:var(--text);
  font-size:var(--font-size-12);
  font-weight:var(--font-weight-950);
  line-height:var(--line-height-1-2);
  text-align:center;
  font-variant-numeric:tabular-nums;
  overflow-wrap:anywhere;
}

.premium-progress {
  display:grid;
  grid-template-columns:var(--icon-frame-xl) minmax(0, 1fr);
  gap:var(--space-12);
  align-items:start;
  min-width:0;
  border:1px solid var(--premium-progress-line);
  border-radius:var(--radius-card);
  padding:var(--space-12);
  background:linear-gradient(135deg, var(--surface-raised), var(--premium-progress-soft));
  box-shadow:var(--shadow-widget);
}

.premium-progress.variant-circular {
  grid-template-columns:auto minmax(0, 1fr);
  align-items:center;
}

.premium-progress-icon {
  display:inline-flex;
  align-items:center;
  justify-content:center;
  width:var(--icon-frame-xl);
  height:var(--icon-frame-xl);
  border:1px solid var(--premium-progress-line);
  border-radius:var(--radius-card);
  background:var(--surface);
  color:var(--premium-progress-color);
  box-shadow:var(--shadow-xs);
}

.premium-progress-content,
.premium-progress-copy {
  display:grid;
  gap:var(--space-8);
  min-width:0;
}

.premium-progress-copy strong {
  color:var(--text);
  font-size:var(--font-size-15);
  font-weight:var(--font-weight-950);
  line-height:var(--line-height-1-25);
  overflow-wrap:anywhere;
}

.premium-progress-copy p,
.premium-progress-extra {
  margin:0;
  color:var(--text-soft);
  font-size:var(--font-size-12);
  font-weight:var(--font-weight-800);
  line-height:var(--line-height-1-4);
  overflow-wrap:anywhere;
}

.premium-progress-extra small {
  color:inherit;
  font:inherit;
}

.premium-loading-overlay {
  display:flex;
  align-items:center;
  justify-content:center;
  min-width:0;
  padding:var(--space-24);
  background:var(--color-rgba-15-23-42-44);
  backdrop-filter:blur(5px);
  animation:motionOverlayIn var(--motion-fast) var(--motion-ease-out);
}

.premium-loading-overlay.mode-fullscreen {
  position:fixed;
  inset:0;
  z-index:160;
}

.premium-loading-overlay.mode-container {
  position:absolute;
  inset:0;
  z-index:20;
  border-radius:inherit;
}

.premium-loading-overlay.mode-inline {
  position:relative;
  border:1px solid var(--line-soft);
  border-radius:var(--radius-card);
  background:linear-gradient(135deg, var(--surface-raised), var(--surface));
  box-shadow:var(--shadow-card);
}

.premium-loading-overlay-shell {
  display:grid;
  justify-items:center;
  gap:var(--space-16);
  width:min(520px, 100%);
  min-width:0;
  border:1px solid var(--line-soft);
  border-radius:var(--radius-card);
  padding:var(--space-20);
  background:linear-gradient(180deg, var(--surface-raised), var(--surface));
  box-shadow:var(--shadow-overlay);
  text-align:center;
}

.premium-loading-overlay-copy {
  display:grid;
  gap:var(--space-4);
  min-width:0;
}

.premium-loading-overlay-copy strong {
  color:var(--text);
  font-size:var(--font-size-18);
  font-weight:var(--font-weight-950);
  line-height:var(--line-height-1-2);
  overflow-wrap:anywhere;
}

.premium-loading-overlay-copy p {
  margin:0;
  color:var(--text-soft);
  font-size:var(--font-size-13);
  font-weight:var(--font-weight-800);
  line-height:var(--line-height-1-45);
  overflow-wrap:anywhere;
}

.premium-loading-overlay .premium-linear-progress {
  width:100%;
}

.premium-loading-overlay-actions {
  display:flex;
  flex-wrap:wrap;
  justify-content:center;
  gap:var(--space-8);
  min-width:0;
}

@keyframes premiumSkeletonShimmer {
  0% { background-position:120% 0 }
  100% { background-position:-120% 0 }
}

@keyframes premiumProgressIndeterminate {
  0% { transform:translateX(-118%) }
  52% { transform:translateX(72%) }
  100% { transform:translateX(172%) }
}

@keyframes premiumLoadingSpin {
  to { transform:rotate(360deg) }
}

@keyframes spin {
  to { transform:rotate(360deg) }
}

@media (max-width: 980px){
  .premium-skeleton-kpi-grid,
  .decision-route-skeleton .premium-skeleton-kpi-grid {
    grid-template-columns:repeat(2, minmax(0, 1fr));
  }

  .premium-skeleton-form {
    grid-template-columns:1fr;
  }
}

@media (max-width: 640px){
  .premium-skeleton-kpi-grid,
  .decision-route-skeleton .premium-skeleton-kpi-grid,
  .premium-progress,
  .premium-progress.variant-circular {
    grid-template-columns:1fr;
  }

  .premium-progress-icon {
    width:var(--icon-frame-lg);
    height:var(--icon-frame-lg);
  }

  .premium-progress-header {
    align-items:flex-start;
    flex-direction:column;
  }

  .premium-loading-overlay {
    padding:var(--space-12);
  }

  .premium-loading-overlay-shell {
    padding:var(--space-16);
  }
}

/* Faz 35.9 Onboarding, Empty States & Product Tour */
.premium-empty-state {
  display:grid;
  grid-template-columns:var(--icon-frame-xxl) minmax(0, 1fr);
  gap:var(--space-16);
  align-items:center;
  min-width:0;
  border:1px dashed var(--line-strong);
  border-radius:var(--radius-card);
  padding:var(--space-20);
  background:linear-gradient(135deg, var(--surface-raised), var(--surface));
  color:var(--text);
  box-shadow:var(--shadow-card);
}

.premium-empty-state.size-compact {
  grid-template-columns:var(--icon-frame-xl) minmax(0, 1fr);
  gap:var(--space-12);
  padding:var(--space-16);
}

.premium-empty-state.size-hero {
  grid-template-columns:var(--icon-frame-xxl) minmax(0, 1fr);
  min-height:176px;
}

.premium-empty-state-visual {
  display:inline-flex;
  align-items:center;
  justify-content:center;
  width:var(--icon-frame-xxl);
  height:var(--icon-frame-xxl);
  border:1px solid var(--accent-line);
  border-radius:var(--radius-card);
  background:var(--accent-soft);
  color:var(--accent);
  box-shadow:var(--shadow-xs);
}

.premium-empty-state.size-compact .premium-empty-state-visual {
  width:var(--icon-frame-xl);
  height:var(--icon-frame-xl);
}

.premium-empty-state.tone-success .premium-empty-state-visual { border-color:var(--success-line); background:var(--success-soft); color:var(--success) }
.premium-empty-state.tone-warning .premium-empty-state-visual { border-color:var(--warning-line); background:var(--warning-soft); color:var(--warning) }
.premium-empty-state.tone-danger .premium-empty-state-visual { border-color:var(--danger-line); background:var(--danger-soft); color:var(--danger) }
.premium-empty-state.tone-neutral .premium-empty-state-visual { border-color:var(--line); background:var(--surface-muted); color:var(--muted-strong) }

.premium-empty-state-copy {
  display:grid;
  gap:var(--space-8);
  min-width:0;
}

.premium-empty-state-eyebrow {
  display:inline-flex;
  align-items:center;
  justify-self:start;
  min-height:24px;
  border:1px solid var(--line);
  border-radius:var(--radius-full);
  padding:var(--space-2) var(--space-8);
  background:var(--surface-muted);
  color:var(--muted-strong);
  font-size:var(--font-size-11);
  font-weight:var(--font-weight-950);
  text-transform:uppercase;
}

.premium-empty-state h3,
.premium-empty-state strong {
  margin:0;
  color:var(--text);
  font-size:var(--font-size-18);
  font-weight:var(--font-weight-950);
  line-height:var(--line-height-1-25);
  overflow-wrap:anywhere;
}

.premium-empty-state p,
.premium-empty-state small,
.premium-empty-state-extra {
  margin:0;
  color:var(--text-soft);
  font-size:var(--font-size-13);
  font-weight:var(--font-weight-800);
  line-height:var(--line-height-1-45);
  overflow-wrap:anywhere;
}

.premium-empty-state-actions,
.premium-empty-actions,
.premium-table-empty-action,
.dashboard-experience-empty-actions {
  display:flex;
  flex-wrap:wrap;
  gap:var(--space-8);
  margin-top:var(--space-8);
}

.premium-table-empty-state.premium-empty-state {
  width:min(100%, 560px);
  margin:0 auto;
  text-align:left;
}

.product-tour-shell {
  position:fixed;
  inset:0;
  z-index:150;
  pointer-events:none;
}

.product-tour-scrim {
  position:absolute;
  inset:0;
  background:var(--color-rgba-15-23-42-18);
  pointer-events:none;
}

.product-tour-shell > div:last-child {
  position:fixed;
  right:24px;
  bottom:24px;
  width:min(430px, calc(100vw - 32px));
  outline:0;
  pointer-events:auto;
}

.product-tour-shell.welcome > div:last-child {
  left:50%;
  right:auto;
  top:50%;
  bottom:auto;
  width:min(540px, calc(100vw - 32px));
  transform:translate(-50%, -50%);
}

.product-tour-card {
  display:grid;
  gap:var(--space-16);
  border:1px solid var(--line-soft);
  border-radius:var(--radius-card);
  padding:var(--space-16);
  background:linear-gradient(180deg, var(--surface-raised), var(--surface));
  color:var(--text);
  box-shadow:var(--shadow-floating);
  animation:motionModalIn var(--motion-normal) var(--motion-ease-spring) both;
}

.product-tour-card-header {
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:var(--space-8);
}

.product-tour-close {
  min-height:36px;
  padding:var(--space-8);
}

.product-tour-copy {
  display:grid;
  grid-template-columns:var(--icon-frame-xl) minmax(0, 1fr);
  gap:var(--space-12);
  align-items:start;
  min-width:0;
}

.product-tour-icon,
.feature-highlight-icon,
.getting-started-card-icon,
.quick-tip-icon {
  display:inline-flex;
  align-items:center;
  justify-content:center;
  width:var(--icon-frame-xl);
  height:var(--icon-frame-xl);
  border:1px solid var(--accent-line);
  border-radius:var(--radius-card);
  background:var(--accent-soft);
  color:var(--accent);
  box-shadow:var(--shadow-xs);
}

.product-tour-copy h3 {
  margin:0;
  color:var(--text);
  font-size:var(--font-size-22);
  font-weight:var(--font-weight-950);
  line-height:var(--line-height-1-2);
  overflow-wrap:anywhere;
}

.product-tour-copy p {
  margin:var(--space-8) 0 0;
  color:var(--text-soft);
  font-size:var(--font-size-14);
  font-weight:var(--font-weight-800);
  line-height:var(--line-height-1-5);
  overflow-wrap:anywhere;
}

.product-tour-progress {
  height:8px;
  overflow:hidden;
  border:1px solid var(--line);
  border-radius:var(--radius-full);
  background:var(--surface-subtle);
}

.product-tour-progress span {
  display:block;
  height:100%;
  border-radius:var(--radius-full);
  background:var(--accent);
  transition:width var(--motion-normal) var(--motion-ease-standard);
}

.product-tour-actions {
  display:flex;
  flex-wrap:wrap;
  justify-content:flex-end;
  gap:var(--space-8);
}

.product-tour-highlight,
.onboarding-highlight {
  position:relative;
  z-index:151;
  outline:3px solid var(--accent);
  outline-offset:4px;
  box-shadow:var(--shadow-highlight-ring) !important;
}

.feature-highlight {
  display:grid;
  grid-template-columns:var(--icon-frame-xl) minmax(0, 1fr) auto;
  gap:var(--space-12);
  align-items:center;
  min-width:0;
  border:1px solid var(--accent-line);
  border-radius:var(--radius-card);
  padding:var(--space-16);
  background:linear-gradient(135deg, var(--accent-soft), var(--surface));
  box-shadow:var(--shadow-card);
}

.feature-highlight.tone-success { border-color:var(--success-line); background:linear-gradient(135deg, var(--success-soft), var(--surface)) }
.feature-highlight.tone-success .feature-highlight-icon { border-color:var(--success-line); background:var(--success-soft); color:var(--success) }
.feature-highlight.tone-warning { border-color:var(--warning-line); background:linear-gradient(135deg, var(--warning-soft), var(--surface)) }
.feature-highlight.tone-warning .feature-highlight-icon { border-color:var(--warning-line); background:var(--warning-soft); color:var(--warning) }
.feature-highlight.tone-danger { border-color:var(--danger-line); background:linear-gradient(135deg, var(--danger-soft), var(--surface)) }
.feature-highlight.tone-danger .feature-highlight-icon { border-color:var(--danger-line); background:var(--danger-soft); color:var(--danger) }

.feature-highlight-copy {
  display:grid;
  gap:var(--space-4);
  min-width:0;
}

.feature-highlight-copy span,
.getting-started-card-badge {
  display:inline-flex;
  justify-self:start;
  min-height:24px;
  border:1px solid var(--line);
  border-radius:var(--radius-full);
  padding:var(--space-2) var(--space-8);
  background:var(--surface);
  color:var(--muted-strong);
  font-size:var(--font-size-11);
  font-weight:var(--font-weight-950);
  line-height:var(--line-height-1-2);
}

.feature-highlight-copy strong {
  color:var(--text);
  font-size:var(--font-size-17);
  font-weight:var(--font-weight-950);
  line-height:var(--line-height-1-25);
  overflow-wrap:anywhere;
}

.feature-highlight-copy p {
  margin:0;
  color:var(--text-soft);
  font-size:var(--font-size-13);
  font-weight:var(--font-weight-800);
  line-height:var(--line-height-1-45);
  overflow-wrap:anywhere;
}

.feature-highlight-actions {
  display:flex;
  flex-wrap:wrap;
  justify-content:flex-end;
  gap:var(--space-8);
}

.getting-started-grid {
  display:grid;
  grid-template-columns:repeat(3, minmax(0, 1fr));
  gap:var(--space-12);
}

.getting-started-card {
  display:grid;
  gap:var(--space-12);
  min-width:0;
  min-height:248px;
  border:1px solid var(--line-soft);
  border-radius:var(--radius-card);
  padding:var(--space-16);
  background:linear-gradient(180deg, var(--surface-raised), var(--surface));
  box-shadow:var(--shadow-card);
  transition:var(--motion-transition-surface);
}

.getting-started-card.disabled {
  opacity:.68;
}

.getting-started-card-header {
  display:flex;
  align-items:flex-start;
  justify-content:space-between;
  gap:var(--space-8);
  min-width:0;
}

.getting-started-card-copy {
  display:grid;
  gap:var(--space-4);
  min-width:0;
}

.getting-started-card-copy h3 {
  margin:0;
  color:var(--text);
  font-size:var(--font-size-17);
  font-weight:var(--font-weight-950);
  line-height:var(--line-height-1-25);
  overflow-wrap:anywhere;
}

.getting-started-card-copy p {
  margin:0;
  color:var(--text-soft);
  font-size:var(--font-size-13);
  font-weight:var(--font-weight-780);
  line-height:var(--line-height-1-45);
  overflow-wrap:anywhere;
}

.getting-started-steps {
  display:grid;
  gap:var(--space-8);
  margin:0;
  padding:0;
  list-style:none;
}

.getting-started-steps li {
  display:grid;
  grid-template-columns:24px minmax(0, 1fr);
  gap:var(--space-8);
  align-items:center;
  min-height:34px;
  border:1px solid var(--line);
  border-radius:var(--radius-card);
  padding:var(--space-4) var(--space-8);
  background:var(--surface-muted);
  color:var(--muted-strong);
}

.getting-started-steps li span {
  display:inline-flex;
  align-items:center;
  justify-content:center;
  width:22px;
  height:22px;
  border:1px solid var(--line);
  border-radius:var(--radius-full);
  background:var(--surface);
  color:var(--muted);
}

.getting-started-steps li.done {
  border-color:var(--success-line);
  background:var(--success-soft);
  color:var(--success);
}

.getting-started-steps li.done span {
  border-color:var(--success-line);
  color:var(--success);
}

.getting-started-steps li strong {
  min-width:0;
  color:inherit;
  font-size:var(--font-size-12);
  font-weight:var(--font-weight-900);
  line-height:var(--line-height-1-25);
  overflow-wrap:anywhere;
}

.getting-started-card .btn {
  align-self:end;
  width:100%;
  margin-top:auto;
}

.quick-tip {
  display:grid;
  grid-template-columns:var(--icon-frame-lg) minmax(0, 1fr) auto;
  gap:var(--space-12);
  align-items:start;
  min-width:0;
  border:1px solid var(--accent-line);
  border-radius:var(--radius-card);
  padding:var(--space-12);
  background:linear-gradient(135deg, var(--accent-soft), var(--surface));
  box-shadow:var(--shadow-xs);
}

.quick-tip.tone-neutral { border-color:var(--line); background:var(--surface-muted) }
.quick-tip.tone-success { border-color:var(--success-line); background:linear-gradient(135deg, var(--success-soft), var(--surface)) }
.quick-tip.tone-warning { border-color:var(--warning-line); background:linear-gradient(135deg, var(--warning-soft), var(--surface)) }
.quick-tip.tone-danger { border-color:var(--danger-line); background:linear-gradient(135deg, var(--danger-soft), var(--surface)) }

.quick-tip-icon {
  width:var(--icon-frame-lg);
  height:var(--icon-frame-lg);
}

.quick-tip-copy {
  display:grid;
  gap:var(--space-4);
  min-width:0;
}

.quick-tip-copy strong {
  color:var(--text);
  font-size:var(--font-size-13);
  font-weight:var(--font-weight-950);
  line-height:var(--line-height-1-25);
}

.quick-tip-copy p {
  margin:0;
  color:var(--text-soft);
  font-size:var(--font-size-12);
  font-weight:var(--font-weight-800);
  line-height:var(--line-height-1-4);
  overflow-wrap:anywhere;
}

.quick-tip-close {
  display:inline-flex;
  align-items:center;
  justify-content:center;
  width:32px;
  height:32px;
  border:1px solid var(--line);
  border-radius:var(--radius-button);
  background:var(--surface);
  color:var(--muted-strong);
  cursor:pointer;
}

.topbar-workspace-tour-target {
  display:inline-flex;
  min-width:0;
}

@media (hover: hover) and (pointer: fine){
  .getting-started-card:hover {
    border-color:var(--accent-line);
    box-shadow:var(--shadow-button-hover);
    transform:translateY(calc(var(--space-2) * -1));
  }
}

@media (max-width: 980px){
  .getting-started-grid {
    grid-template-columns:repeat(2, minmax(0, 1fr));
  }

  .feature-highlight {
    grid-template-columns:var(--icon-frame-xl) minmax(0, 1fr);
  }

  .feature-highlight-actions {
    grid-column:1 / -1;
    justify-content:flex-start;
  }
}

@media (max-width: 640px){
  .premium-empty-state,
  .premium-empty-state.size-compact,
  .premium-empty-state.size-hero,
  .product-tour-copy,
  .feature-highlight,
  .quick-tip,
  .getting-started-grid {
    grid-template-columns:1fr;
  }

  .product-tour-shell > div:last-child {
    right:16px;
    bottom:16px;
    width:calc(100vw - 32px);
  }

  .product-tour-shell.welcome > div:last-child {
    width:calc(100vw - 32px);
  }

  .product-tour-actions,
  .product-tour-actions .btn,
  .premium-empty-state-actions .btn,
  .feature-highlight-actions .btn {
    width:100%;
  }

  .premium-table-empty-state.premium-empty-state {
    justify-items:center;
    text-align:center;
  }
}

/* Faz 35.10 Premium Theme Engine */
html[data-theme-engine="premium"] {
  background:var(--theme-app-bg);
  color:var(--theme-text-primary);
}

html[data-theme-engine="premium"] body {
  background:var(--theme-app-bg);
  color:var(--theme-text-primary);
}

html[data-theme-engine="premium"] body,
html[data-theme-engine="premium"] input,
html[data-theme-engine="premium"] select,
html[data-theme-engine="premium"] textarea,
html[data-theme-engine="premium"] button {
  font-family:var(--theme-typography-body);
}

.theme-surface,
.theme-elevation,
.glass-surface {
  min-width:0;
  color:var(--theme-text-primary);
  transition:var(--theme-motion-surface);
}

.surface-level-0 { --theme-current-surface:var(--theme-surface-0) }
.surface-level-1 { --theme-current-surface:var(--theme-surface-1) }
.surface-level-2 { --theme-current-surface:var(--theme-surface-2) }
.surface-level-3 { --theme-current-surface:var(--theme-surface-3) }
.surface-level-4 { --theme-current-surface:var(--theme-surface-4) }

.theme-surface {
  background:var(--theme-current-surface, var(--theme-surface-1));
  border-color:var(--theme-border-default);
}

.elevation-level-0 {
  --theme-current-elevation-background:var(--theme-elevation-0-background);
  --theme-current-elevation-border:var(--theme-elevation-0-border);
  --theme-current-elevation-shadow:var(--theme-elevation-0-shadow);
  --theme-current-elevation-blur:var(--theme-elevation-0-blur);
}

.elevation-level-1 {
  --theme-current-elevation-background:var(--theme-elevation-1-background);
  --theme-current-elevation-border:var(--theme-elevation-1-border);
  --theme-current-elevation-shadow:var(--theme-elevation-1-shadow);
  --theme-current-elevation-blur:var(--theme-elevation-1-blur);
}

.elevation-level-2 {
  --theme-current-elevation-background:var(--theme-elevation-2-background);
  --theme-current-elevation-border:var(--theme-elevation-2-border);
  --theme-current-elevation-shadow:var(--theme-elevation-2-shadow);
  --theme-current-elevation-blur:var(--theme-elevation-2-blur);
}

.elevation-level-3 {
  --theme-current-elevation-background:var(--theme-elevation-3-background);
  --theme-current-elevation-border:var(--theme-elevation-3-border);
  --theme-current-elevation-shadow:var(--theme-elevation-3-shadow);
  --theme-current-elevation-blur:var(--theme-elevation-3-blur);
}

.theme-elevation {
  border:1px solid var(--theme-current-elevation-border, var(--theme-border-subtle));
  background:var(--theme-current-elevation-background, var(--theme-surface-1));
  box-shadow:var(--theme-current-elevation-shadow, var(--theme-shadow-sm));
  backdrop-filter:var(--theme-current-elevation-blur, var(--theme-blur-none));
}

.glass-sidebar {
  --theme-current-glass-background:var(--theme-glass-sidebar-background);
  --theme-current-glass-border:var(--theme-glass-sidebar-border);
  --theme-current-glass-shadow:var(--theme-glass-sidebar-shadow);
  --theme-current-glass-blur:var(--theme-glass-sidebar-blur);
}

.glass-topbar {
  --theme-current-glass-background:var(--theme-glass-topbar-background);
  --theme-current-glass-border:var(--theme-glass-topbar-border);
  --theme-current-glass-shadow:var(--theme-glass-topbar-shadow);
  --theme-current-glass-blur:var(--theme-glass-topbar-blur);
}

.glass-card {
  --theme-current-glass-background:var(--theme-glass-card-background);
  --theme-current-glass-border:var(--theme-glass-card-border);
  --theme-current-glass-shadow:var(--theme-glass-card-shadow);
  --theme-current-glass-blur:var(--theme-glass-card-blur);
}

.glass-modal {
  --theme-current-glass-background:var(--theme-glass-modal-background);
  --theme-current-glass-border:var(--theme-glass-modal-border);
  --theme-current-glass-shadow:var(--theme-glass-modal-shadow);
  --theme-current-glass-blur:var(--theme-glass-modal-blur);
}

.glass-drawer {
  --theme-current-glass-background:var(--theme-glass-drawer-background);
  --theme-current-glass-border:var(--theme-glass-drawer-border);
  --theme-current-glass-shadow:var(--theme-glass-drawer-shadow);
  --theme-current-glass-blur:var(--theme-glass-drawer-blur);
}

.glass-dropdown {
  --theme-current-glass-background:var(--theme-glass-dropdown-background);
  --theme-current-glass-border:var(--theme-glass-dropdown-border);
  --theme-current-glass-shadow:var(--theme-glass-dropdown-shadow);
  --theme-current-glass-blur:var(--theme-glass-dropdown-blur);
}

.glass-surface {
  border:1px solid var(--theme-current-glass-border, var(--theme-glass-card-border));
  background:var(--theme-current-glass-background, var(--theme-glass-card-background));
  box-shadow:var(--theme-current-glass-shadow, var(--theme-glass-card-shadow));
  backdrop-filter:var(--theme-current-glass-blur, var(--theme-glass-card-blur));
  -webkit-backdrop-filter:var(--theme-current-glass-blur, var(--theme-glass-card-blur));
}

html[data-theme-engine="premium"] :where(.app-shell, .app-main) {
  background:var(--theme-app-bg);
}

html[data-theme-engine="premium"] .workspace-scroll-region {
  background:var(--theme-app-canvas);
}

html[data-theme-engine="premium"] :where(.app-content, .workspace-layout, .workspace-content-shell, .workspace-content) {
  color:var(--theme-text-primary);
}

html[data-theme-engine="premium"] .side-nav {
  border-right-color:var(--theme-glass-sidebar-border);
  background:var(--theme-glass-sidebar-background);
  box-shadow:var(--theme-glass-sidebar-shadow);
  backdrop-filter:var(--theme-glass-sidebar-blur);
  -webkit-backdrop-filter:var(--theme-glass-sidebar-blur);
}

html[data-theme-engine="premium"] .topbar {
  border-bottom-color:var(--theme-glass-topbar-border);
  background:var(--theme-glass-topbar-background);
  box-shadow:var(--theme-glass-topbar-shadow);
  backdrop-filter:var(--theme-glass-topbar-blur);
  -webkit-backdrop-filter:var(--theme-glass-topbar-blur);
}

html[data-theme-engine="premium"] :where(
  .card,
  .premium-card,
  .premium-widget,
  .premium-skeleton-block,
  .premium-skeleton-hero,
  .premium-progress,
  .premium-loading-overlay-shell,
  .premium-empty-state,
  .product-tour-card,
  .feature-highlight,
  .getting-started-card,
  .quick-tip,
  .dashboard-panel,
  .metric-card,
  .dashboard-kpi-card,
  .dashboard-widget-card,
  .dashboard-widget-catalog-card,
  .workspace-welcome-panel,
  .report-center-card,
  .report-kpi-card,
