/* Faz 35.11 Responsive Experience */
.responsive-container {
  width:min(100%, var(--responsive-container-width, var(--responsive-container-current)));
  min-width:0;
  margin-inline:auto;
  padding-inline:var(--responsive-container-padding, var(--responsive-page-padding));
}

.responsive-container.size-wide { --responsive-container-width:var(--responsive-container-wide) }
.responsive-container.size-page { --responsive-container-width:var(--responsive-container-current) }
.responsive-container.size-content { --responsive-container-width:min(100%, 1120px) }
.responsive-container.size-full { --responsive-container-width:100% }
.responsive-container.padding-none { --responsive-container-padding:0 }
.responsive-container.padding-compact { --responsive-container-padding:var(--space-12) }
.responsive-container.padding-comfortable { --responsive-container-padding:var(--responsive-page-padding) }

.responsive-grid {
  display:grid;
  grid-template-columns:repeat(var(--responsive-grid-wide-columns, var(--responsive-grid-desktop-columns, 4)), minmax(0, 1fr));
  gap:var(--responsive-grid-gap-current, var(--responsive-grid-gap));
  align-items:stretch;
  min-width:0;
}

.responsive-grid.gap-compact { --responsive-grid-gap-current:var(--space-8) }
.responsive-grid.gap-comfortable { --responsive-grid-gap-current:var(--responsive-grid-gap) }
.responsive-grid.gap-spacious { --responsive-grid-gap-current:var(--space-20) }

.responsive-grid.fit-auto-fit {
  grid-template-columns:repeat(auto-fit, minmax(min(100%, var(--responsive-grid-min-column, var(--responsive-card-min))), 1fr));
}

.responsive-grid.fit-auto-fill {
  grid-template-columns:repeat(auto-fill, minmax(min(100%, var(--responsive-grid-min-column, var(--responsive-card-min))), 1fr));
}

.responsive-layout {
  display:grid;
  gap:var(--responsive-layout-gap-current, var(--responsive-section-gap));
  min-width:0;
}

.responsive-layout.gap-compact { --responsive-layout-gap-current:var(--space-8) }
.responsive-layout.gap-comfortable { --responsive-layout-gap-current:var(--responsive-section-gap) }
.responsive-layout.gap-spacious { --responsive-layout-gap-current:var(--space-24) }
.responsive-layout.variant-stack { grid-template-columns:minmax(0, 1fr) }
.responsive-layout.variant-split { grid-template-columns:minmax(0, 1fr) minmax(min(100%, 360px), .42fr) }
.responsive-layout.variant-sidebar { grid-template-columns:minmax(220px, var(--responsive-layout-sidebar-width, 320px)) minmax(0, 1fr) }
.responsive-layout.variant-dashboard { grid-template-columns:repeat(12, minmax(0, 1fr)) }
.responsive-layout > * { min-width:0 }

.responsive-card {
  display:grid;
  gap:var(--responsive-card-gap, var(--space-12));
  min-width:0;
  border:1px solid var(--line-soft);
  border-radius:var(--radius-card);
  padding:var(--responsive-card-padding);
  background:linear-gradient(180deg, var(--surface-raised), var(--surface));
  color:var(--text);
  box-shadow:var(--shadow-card);
  transition:var(--motion-transition-surface);
}

.responsive-card.density-compact {
  --responsive-card-gap:var(--space-8);
  padding:var(--space-12);
}

.responsive-card.interactive {
  cursor:pointer;
}

.responsive-table {
  width:100%;
  max-width:100%;
  min-width:0;
  overflow-x:auto;
  overscroll-behavior-x:contain;
  -webkit-overflow-scrolling:touch;
  scrollbar-gutter:stable;
}

.responsive-table:focus-visible {
  outline:2px solid var(--accent);
  outline-offset:var(--space-2);
}

.responsive-table > table {
  min-width:var(--responsive-table-min-width);
}

.responsive-table.mode-scroll > table {
  min-width:var(--responsive-table-min-width, 760px);
}

.responsive-table.mode-cards > table {
  min-width:0;
}

.responsive-table .data-table td[data-label],
.responsive-table .premium-table td[data-label] {
  overflow-wrap:anywhere;
}

@media (hover: hover) and (pointer: fine){
  .responsive-card.interactive:hover {
    border-color:var(--accent-line);
    box-shadow:var(--shadow-button-hover);
    transform:translateY(calc(var(--space-2) * -1));
  }
}

