  .responsive-table.mode-cards thead,
  .responsive-table.mode-hybrid thead {
    position:absolute;
    width:1px;
    height:1px;
    margin:-1px;
    overflow:hidden;
    clip:rect(0, 0, 0, 0);
    white-space:nowrap;
    border:0;
    padding:0;
  }

  .responsive-table.mode-cards tbody,
  .responsive-table.mode-hybrid tbody {
    display:grid;
    gap:var(--space-12);
    padding:0;
