  .responsive-table.mode-cards tbody tr,
  .responsive-table.mode-hybrid tbody tr {
    display:grid;
    min-width:0;
    overflow:hidden;
    border:1px solid var(--line-soft);
    border-radius:var(--radius-card);
    background:var(--surface);
    box-shadow:var(--shadow-card);
  }

  .responsive-table.mode-cards tbody td,
  .responsive-table.mode-hybrid tbody td {
    display:grid;
    grid-template-columns:minmax(112px, .42fr) minmax(0, 1fr);
    gap:var(--space-8);
    align-items:start;
    min-height:auto;
    border-bottom:1px solid var(--line-soft);
    padding:var(--space-8) var(--space-12);
    background:transparent !important;
    color:var(--text);
    text-align:left !important;
    white-space:normal !important;
  }

  .responsive-table.mode-cards tbody td:last-child,
  .responsive-table.mode-hybrid tbody td:last-child {
    border-bottom:0;
  }

  .responsive-table.mode-cards tbody td::before,
  .responsive-table.mode-hybrid tbody td::before {
    content:attr(data-label);
    min-width:0;
    color:var(--muted-strong);
    font-size:var(--font-size-11);
    font-weight:var(--font-weight-950);
    line-height:var(--line-height-1-25);
    text-transform:uppercase;
