  .responsive-table.mode-cards tbody td:not([data-label]),
  .responsive-table.mode-hybrid tbody td:not([data-label]),
  .responsive-table.mode-cards tbody td[data-label=""],
  .responsive-table.mode-hybrid tbody td[data-label=""],
  .responsive-table.mode-cards tbody td.empty-cell,
  .responsive-table.mode-hybrid tbody td.empty-cell,
  .responsive-table.mode-cards tbody td.premium-table-empty-cell,
  .responsive-table.mode-hybrid tbody td.premium-table-empty-cell,
  .responsive-table.mode-cards tbody td.actions-cell,
  .responsive-table.mode-hybrid tbody td.actions-cell {
    grid-template-columns:1fr;
  }

  .responsive-table.mode-cards .premium-table-empty-row,
  .responsive-table.mode-hybrid .premium-table-empty-row,
  .responsive-table.mode-cards .premium-table-loading-row,
  .responsive-table.mode-hybrid .premium-table-loading-row {
    border:0;
    background:transparent;
    box-shadow:var(--shadow-none);
  }

  .responsive-table.mode-cards .premium-table-empty-cell,
  .responsive-table.mode-hybrid .premium-table-empty-cell {
    padding:0;
  }

  .responsive-table.mode-cards td.actions-cell .btn,
  .responsive-table.mode-hybrid td.actions-cell .btn,
  .responsive-table.mode-cards td.actions-cell .icon-btn,
  .responsive-table.mode-hybrid td.actions-cell .icon-btn {
    width:100%;
    min-width:0;
  }

  .premium-table-shell {
    display:grid;
    gap:var(--space-12);
  }

  .premium-table-toolbar,
  .premium-table-toolbar-controls,
  .premium-table-filters,
  .premium-table-actions,
  .premium-table-bulk-actions,
  .premium-pagination,
  .premium-form-actions,
