  --layout-card-padding:var(--space-20);
  --layout-card-gap:var(--space-12);
  --premium-control-height:var(--edl-density-control);
  --premium-icon-button-size:var(--edl-density-icon-button);
  --premium-icon-frame:var(--edl-icon-frame);
  --premium-layer-border:var(--edl-border-subtle);
  --premium-layer-border-strong:var(--edl-border-default);
  --premium-card-fill:var(--edl-surface-card);
  --premium-card-fill-hover:var(--edl-surface-card-hover);
  --premium-control-fill:var(--edl-surface-control);
  --premium-chrome-fill:var(--edl-surface-chrome);
  --premium-nav-selected:var(--edl-surface-selected);
  --premium-nav-hover:linear-gradient(90deg, color-mix(in srgb, var(--theme-state-hover) 74%, transparent), transparent);
  --motion-fast:var(--edl-motion-fast);
  --motion-normal:var(--edl-motion-standard);
  --motion-medium:var(--edl-motion-standard);
  --motion-slow:var(--edl-motion-slow);
  --motion-hover-lift:1px;
}

html[data-theme="dark"][data-theme-engine="premium"] {
  --premium-card-fill:linear-gradient(180deg, var(--theme-surface-1), var(--theme-surface-0));
  --premium-card-fill-hover:linear-gradient(180deg, color-mix(in srgb, var(--theme-surface-2) 90%, var(--theme-semantic-primary-soft)), var(--theme-surface-1));
  --premium-control-fill:linear-gradient(180deg, var(--theme-surface-2), color-mix(in srgb, var(--theme-surface-1) 92%, var(--theme-surface-0)));
  --premium-chrome-fill:linear-gradient(180deg, var(--theme-surface-1), var(--theme-surface-0));
