  --enterprise-theme-primary-action:linear-gradient(180deg, var(--theme-semantic-primary-base), color-mix(in srgb, var(--theme-semantic-primary-hover) 86%, var(--theme-semantic-primary-base)));
  --enterprise-theme-primary-action-hover:linear-gradient(180deg, var(--theme-semantic-primary-hover), color-mix(in srgb, var(--theme-semantic-primary-hover) 82%, var(--theme-color-black)));
