@keyframes motionPageContentIn {
  from { opacity:.82; transform:translateY(var(--motion-enter-distance-sm)) }
  to { opacity:1; transform:translateY(0) }
}

@keyframes motionSlideUpIn {
  from { opacity:0; transform:translateY(var(--motion-enter-distance)) }
  to { opacity:1; transform:translateY(0) }
}

@keyframes motionSlideRightIn {
  from { opacity:0; transform:translateX(calc(var(--motion-enter-distance) * -1)) }
  to { opacity:1; transform:translateX(0) }
}

@keyframes motionSlideDownIn {
  from { opacity:0; transform:translateY(calc(var(--motion-enter-distance) * -1)) }
  to { opacity:1; transform:translateY(0) }
}

@keyframes motionSlideLeftIn {
  from { opacity:0; transform:translateX(var(--motion-enter-distance)) }
  to { opacity:1; transform:translateX(0) }
}

@keyframes motionScaleIn {
  from { opacity:0; transform:scale(.985) }
  to { opacity:1; transform:scale(1) }
}

@keyframes motionOverlayIn {
  from { opacity:0 }
  to { opacity:1 }
}

